from itertools import product

imp = lambda a, b: (not a) or b
oncul_dogru = 0
karsi_ornek = 0
for p, q, r in product([True, False], repeat=3):
    if imp(p, q) and imp(q, r):
        oncul_dogru += 1
        if not imp(p, r):
            karsi_ornek += 1
print(oncul_dogru, karsi_ornek)

def sonra(taban, duyarlilik, yanlis_alarm):
    dogru = taban * duyarlilik
    yanlis = (1 - taban) * yanlis_alarm
    return round(dogru / (dogru + yanlis), 3)

print(sonra(0.05, 0.8, 0.1), sonra(0.30, 0.8, 0.1))

gruplar = {
    "yeni": {"P9": (2, 50), "ST": (10, 200)},
    "eski": {"P9": (45, 150), "ST": (20, 50)},
}
for grup, v in gruplar.items():
    p9 = round(100 * v["P9"][0] / v["P9"][1], 1)
    st = round(100 * v["ST"][0] / v["ST"][1], 1)
    print(grup, p9, st)
for ad in ["P9", "ST"]:
    x = sum(gruplar[g][ad][0] for g in gruplar)
    n = sum(gruplar[g][ad][1] for g in gruplar)
    print(ad, round(100 * x / n, 1))

